pub fn moved(s: Shape, d: Vec2) -> Shape {
  match s {
    c @ Circle { center, .. } => Circle { center: add(center), ..c },
    r @ Rect { min, max } => Rect { min: add(min), max: add(max), ..r },
    l @ Label { at, .. } => Label { at: add(at), ..l },
  }
}
